INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65319680', 65319680, 'analyze_legacy', 'Komisi Pemilihan Umum', 'central', 'KPU  KABUPATEN WONOGIRI', 'Paket Belanja Pemeliharaan Peralatan dan Mesin dalam rangka pelaksanaan kegiatan Pelayanan Operasional Kantor dan Dukungan Sarana Prasarana', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Tengah, Wonogiri (Kab.)', 65150000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Kendaraan Roda 4 (APBN) ( 1, Unit, @ 5600000 ); 2. Kendaraan Roda 2 (APBN) ( 1, Unit, @ 50000 ); 3. Servis Komputer/Laptop/AC/Lainnya ( 1, PKT, @ 50000 ); 4. Servis Peralatan dan Mesin ( 1, PKT, @ 59450000 );', '1. Pemeliharaan Kendaraan Roda Empat (APBN) Pemeliharaan kendaraan dinas roda empat sebanyak 1 (satu) unit, dengan nilai satuan Rp5.600.000. Ruang lingkup pemeliharaan meliputi servis berkala kendaraan, pemeriksaan dan penyetelan mesin, penggantian oli dan suku cadang ringan, pemeriksaan sistem kelistrikan, rem, dan komponen pendukung lainnya agar kendaraan tetap laik jalan dan aman digunakan untuk mendukung kegiatan kedinasan. 2. Pemeliharaan Kendaraan Roda Dua (APBN) Pemeliharaan kendaraan dinas roda dua sebanyak 1 (satu) unit, dengan nilai satuan Rp50.000. Pemeliharaan meliputi servis ringan kendaraan, pengecekan kondisi mesin, rantai, rem, serta komponen pendukung lainnya guna memastikan kendaraan berfungsi dengan baik dan mendukung mobilitas operasional. 3. Servis Komputer/Laptop/AC dan Peralatan Sejenis Servis peralatan teknologi dan penunjang perkantoran sebanyak 1 (satu) paket, dengan nilai Rp50.000. Ruang lingkup pekerjaan meliputi pemeriksaan, pembersihan, penyetelan, dan perbaikan ringan komputer, laptop, AC, dan peralatan sejenis lainnya, termasuk pengujian fungsi agar peralatan dapat digunakan secara optimal dalam mendukung kegiatan administrasi dan teknis. 4. Servis Peralatan dan Mesin Servis peralatan dan mesin sebanyak 1 (satu) paket, dengan nilai Rp59.450.000. Pemeliharaan meliputi pemeriksaan menyeluruh, perawatan, perbaikan ringan hingga sedang, serta penggantian komponen kecil pada peralatan dan mesin perkantoran sesuai kebutuhan, guna menjaga kinerja, keamanan, dan keberlanjutan operasional peralatan dalam mendukung tugas dan fungsi kelembagaan.', 59450000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2076229);
