INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65319679', 65319679, 'analyze_legacy', 'Komisi Pemilihan Umum', 'central', 'KPU  KABUPATEN WONOGIRI', 'Belanja Keperluan Perkantoran Dalam Rangka Pelaksanaan Pelayanan Operasional Kantor dan Dukungan Sarana Prasarana', 'Barang', 'Pengadaan Langsung', 'Jawa Tengah, Wonogiri (Kab.)', 106770000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. ATK, Jamuan Makan/Konsumsi, Alat Rumah Tangga, Barang Cetak, Langganan koran/majalah dan Air Minum pegawai ( 1, PKT, @ 100000000 ); 2. Penggantian Inventaris Lama ( 1, PKT, @ 6770000 );', '1. ATK, Jamuan Makan/Konsumsi, Alat Rumah Tangga, Barang Cetak, Langganan Koran/Majalah, dan Air Minum Pegawai Pengadaan meliputi penyediaan barang dan jasa penunjang operasional perkantoran dan pelaksanaan kegiatan, dengan ruang lingkup sebagai berikut: Alat Tulis Kantor (ATK) Perlengkapan administrasi perkantoran yang digunakan dalam kegiatan sehari-hari dan kegiatan teknis, antara lain kertas HVS ukuran A4/F4, pulpen, pensil, spidol, map, buku catatan, dan perlengkapan ATK lainnya sesuai kebutuhan. ATK dalam kondisi baru, layak pakai, dan sesuai standar kualitas perkantoran. Jamuan Makan/Konsumsi Penyediaan konsumsi berupa makanan dan/atau minuman bagi pegawai dan peserta kegiatan sesuai waktu pelaksanaan kegiatan. Konsumsi harus memenuhi standar kebersihan, kelayakan konsumsi, dan disajikan tepat waktu. Alat Rumah Tangga Kantor Peralatan penunjang kebersihan dan kenyamanan kantor, antara lain perlengkapan kebersihan, peralatan dapur kantor, dan perlengkapan rumah tangga lainnya yang mendukung operasional perkantoran. Barang Cetak Pengadaan bahan cetak berupa dokumen, formulir, atau media cetak lainnya yang digunakan untuk kebutuhan administrasi dan kegiatan teknis, dengan hasil cetak jelas, rapi, dan sesuai kebutuhan. Langganan Koran/Majalah Penyediaan layanan langganan media cetak atau digital berupa koran dan/atau majalah sebagai sumber informasi dan referensi bagi pegawai sesuai kebutuhan kantor. Air Minum Pegawai Penyediaan air minum dalam kemasan atau galon untuk kebutuhan pegawai, dalam kondisi layak konsumsi dan sesuai standar kesehatan. 2. Penggantian Inventaris Lama Penggantian inventaris lama meliputi penyediaan barang pengganti atas inventaris perkantoran yang telah rusak, usang, atau tidak layak pakai, guna mendukung kelancaran operasional perkantoran. Barang pengganti berupa peralatan dan perlengkapan kantor sesuai kebutuhan, dengan kondisi baru, berfungsi baik, dan memenuhi standar kualitas peralatan perkantoran. Penggantian dilakukan berdasarkan kebutuhan riil dan ketentuan pengelolaan barang milik negara yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2076808);
