INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65358101', 65358101, 'analyze_legacy', 'Kementerian  Kehutanan', 'central', '693527 BALAI PENGELOLAAN HUTAN LESTARI WILAYAH XIII', 'Pengadaan Jasa Tenaga Kerja Kebersihan dan Pengemudi pada Kantor BPHL Wilayah XIII Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Timur, Samarinda (Kota)', 240006000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 13, Bulan, @ 18462000 )', '1. Tenaga Kebersihan (3 orang) Kalimantan Timur ( 13, Bulan, @ 4.615.500 ); 2. Tenaga Pengemudi (1 orang) Kalimantan Timur ( 13, Bulan, @ 4.615.500)', 'Spesfikasi Teknis Pekerjaan : Ruang Lingkup Pekerjaan Spesifikasi Jasa Tenaga Kebersihan (Cleaning Service) : A. Pembersihan ruang kerja, ruang rapat, ruang tunggu, dan ruang laktasi, meliputi: - Meubelair, peralatan kantor, dan alat makan; - Dinding, sekat/partisi, pintu, jendela, ventilasi; - Langit-langit dan balkon luar ruang kerja; - Pengumpulan dan pembuangan sampah. B. Pembersihan dapur dan toilet/kamar mandi/WC pimpinan, meliputi: - Lantai, dinding, wastafel, cermin; - Urinoir, kloset, saluran air; - Pintu, jendela, dan langit-langit. C. Pembersihan: - Selasar, teras, balkon, dan dinding luar bangunan; - Lobby, tangga, dinding marmer/keramik, terali tangga; - Musholla. D. Pemeliharaan kebersihan halaman kantor dan rumah dinas pimpinan: - Pemotongan rumput; - Pembersihan gulma; - Perawatan tanaman (penyiraman, penggemburan, pemupukan). E. Pembersihan saluran air dan selokan di area kantor. F. Pelaksanaan tugas lain yang diberikan pimpinan sepanjang berkaitan dengan kebersihan lingkungan kantor. Ruang Lingkup Pekerjaan Spesifikasi Jasa Tenaga Pengemudi : A. Memeriksa kelengkapan surat – surat kendaraan dinas; B. Mengemudikan kendaraan dinas untuk keperluan kedinasan sesuai perintah pimpinan; C. Menjaga kebersihan, keamanan, dan kelayakan kendaraan dinas; D. Melaksanakan tugas tambahan lain yang berkaitan dengan fungsi pengemudian sesuai arahan pimpinan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2076820);
