INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65319676', 65319676, 'analyze_legacy', 'Komisi Pemilihan Umum', 'central', 'KPU  KABUPATEN WONOGIRI', 'Belanja Jasa Lainnya Berupa Jasa Internet dalam rangka Pelaksanaan Pelayanan Operasional Kantor dan Dukungan Sarana Prasarana', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Tengah, Wonogiri (Kab.)', 65000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Belanja Jasa Internet ( 1, PKT, @ 15000000 ); 2. Biaya Jasa Lainnya ( 1, PKT, @ 50000000 );', '1. Belanja Jasa Internet Belanja Jasa Internet meliputi penyediaan layanan akses internet untuk mendukung operasional perkantoran dan pelaksanaan tugas serta fungsi KPU Kabupaten/Kota. Layanan internet digunakan untuk kegiatan administrasi, pengelolaan data dan sistem informasi kepemiluan, komunikasi kedinasan, serta pelaksanaan kegiatan teknis penyelenggaraan Pemilu dan Pilkada. Layanan internet disediakan dengan kualitas koneksi yang stabil dan berkelanjutan sesuai kebutuhan operasional kantor, serta disesuaikan dengan ketersediaan layanan dan ketentuan dari penyedia jasa. Pelaksanaan layanan mengikuti masa langganan sesuai periode yang ditetapkan. 2. Biaya Jasa Lainnya Biaya Jasa Lainnya meliputi penyediaan berbagai jasa pendukung yang diperlukan dalam rangka mendukung pelaksanaan tugas dan fungsi kelembagaan serta kegiatan teknis penyelenggaraan Pemilu dan Pilkada. Ruang lingkup jasa lainnya mencakup jasa pendukung administrasi dan teknis yang tidak dapat diklasifikasikan secara spesifik pada jenis jasa tertentu, antara lain jasa dokumentasi kegiatan, jasa pendukung teknis, atau jasa lain sesuai kebutuhan. Pelaksanaan jasa disesuaikan dengan kebutuhan riil kegiatan dan ketentuan peraturan perundang-undangan yang berlaku.', 50000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2077220);
