INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65361472', 65361472, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Jasa Konsultan Penyusunan Bahan Kajian dan Perumusan Strategi Pembangunan Infrastruktur Berkelanjutan', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 148500000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 0, 1, '9', 'Penyusunan analisis, kajian, dan rekomendasi strategis pembangunan infrastruktur berkelanjutan. Mengidentifikasi isu strategis dalam pelaksanaan pembangunan infrastruktur berkelanjutan. Menyusun analisis kebutuhan (needs assessment) dalam pembangunan infrastruktur berkelanjutan yang mempertimbangkan target penurunan emisi GRK, prioritas pembangunan nasional, proyeksi permintaan, serta aspek lainnya yang relevan. Menyusun telaah kebijakan (policy review) terhadap regulasi, kebijakan, dan/atau NSPK pada kementerian/lembaga yang menjadi acuan pelaksanaan pembangunan infrastruktur berkelanjutan. Melakukan benchmarking terhadap praktik-praktik terbaik (best practices) pembangunan infrastruktur berkelanjutan pada tingkat internasional. Menyusun analisis keberlanjutan awal (preliminary sustainability assessment) mencakup aspek teknis, ekonomi, sosial, dan lingkungan terhadap proyek-proyek pembangunan infrastruktur strategis.', '1) Persyaratan Umum a) Memiliki pengalaman kerja paling sedikit 1 (satu) pekerjaan dalam kurun waktu 5 (lima) tahun terakhir dil lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak. b) Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan). c) Memiliki nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran. 2) Persyaratan Pendidikan Memiliki latar belakang pendidikan Teknik Sipil, Teknik Geologi, Teknik Lingkungan, Environmental Studies atau keilmuan lain yang linear dengan jenjang Strata 2 (Magister). 3) Persyaratan Khusus a) Memiliki pengalaman kerja umum minimum 4 (empat) tahun dan 3 (tiga) tahun di bidang sejenis (perencanaan strategis, perencanaan pembangunan, dan kebijakan publik) yang dibuktikan melalui pengalaman kerja yang tertera dalam CV. b) Memiliki pengalaman kerja merancang, mengomunikasikan, dan mengoordinasikan pekerjaan lintas bidang atau lintas level pemerintahan dengan pihak-pihak internal maupun eksternal dalam sebuah program atau kegiatan yang dibuktikan melalui dokumen kontrak kerja. c) Memiliki pengalaman dan kemampuan dalam penulisan ilimiah yang dibuktikan melalui portofolio, CV, atau dokumen sejenisnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2078161);
